-- Apply only after exact reviewed classifier replacement in same fenced transaction.
DO $repair$
DECLARE ctl jsonb;q population_top3000_202608_202609_v1.continuation_clear_queue_v6%rowtype;new_id text;ev bigint;prior jsonb;
BEGIN
 ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 SELECT * INTO STRICT q FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id='3b7a37a6a455cbe44834d1031c6284089954f11e12adde175cc32320e48499fc' FOR UPDATE;
 IF q.status IS DISTINCT FROM 'BLOCKED_EXTERNAL' OR q.kind IS DISTINCT FROM 'EXTERNAL_CONDITION' OR q.attempts<>0 OR q.claimed_at IS NOT NULL OR q.input_sha256<>'52d20bb45f55d920862b303551c538e4ec2718ba75f7579843b4e382883aead0' OR q.blocker_code<>'CTX14_AUTHENTIC_SETTLEMENT_SOURCE_RESOLUTION_REQUIRED' OR q.owner_id<>ctl->>'owner_id' OR q.owner_fence<>3 OR q.stop_generation<>1 THEN RAISE EXCEPTION 'CLASSIFIER_V7_EXACT_UNEXECUTED_PREIMAGE_REQUIRED';END IF;
 IF population_top3000_202608_202609_v1.continuation_classify_v6('CTX14','ACQUIRE',q.blocker_code)<>'SOURCE_RECOVERY' OR population_top3000_202608_202609_v1.continuation_classify_v6('CTX07','ACQUIRE','CTX07_V6_ENFORCED_ACCESS_DENIAL')<>'EXTERNAL_CONDITION' OR population_top3000_202608_202609_v1.continuation_classify_v6('CTX07','ACQUIRE','CTX07_AUTH_FAILED')<>'EXTERNAL_CONDITION' THEN RAISE EXCEPTION 'CLASSIFIER_V7_SOURCE_ACCESS_BOUNDARY_FAILED';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='CTX14' AND status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE family_id='CTX14' AND status='CLAIMED') THEN RAISE EXCEPTION 'CLASSIFIER_V7_COMPONENT_ACTIVE';END IF;
 SELECT details INTO STRICT prior FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=q.assignment_event_id;
 new_id:=q.clearing_id||':classification-v7';
 UPDATE population_top3000_202608_202609_v1.continuation_clear_queue_v6 SET status='SUPERSEDED',last_receipt=last_receipt||jsonb_build_object('reason','AUTH_SUBSTRING_FALSE_MATCH_ON_AUTHENTIC','effects_known',true,'implementation_executed',false,'successor_clearing_id',new_id),updated_at=clock_timestamp() WHERE clearing_id=q.clearing_id;
 INSERT INTO population_top3000_202608_202609_v1.continuation_clear_queue_v6(clearing_id,kind,family_id,blocker_code,input_manifest,input_sha256,status,owner_id,owner_fence,stop_generation,scope_sha256,not_after,last_receipt)
 VALUES(new_id,'SOURCE_RECOVERY',q.family_id,q.blocker_code,q.input_manifest,q.input_sha256,'READY',q.owner_id,q.owner_fence,q.stop_generation,q.scope_sha256,(ctl->>'not_after')::timestamptz,jsonb_build_object('superseded_clearing_id',q.clearing_id,'original_source_holds_preserved',true,'classification_only',true));
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ENGINEERING_CLEARING_ASSIGNMENT_V6',prior||ctl||jsonb_build_object('assignment_id','clearing-v6:'||new_id,'clearing_id',new_id,'kind','SOURCE_RECOVERY','exclusive_component','SOURCE_RECOVERY:CTX14','new_provider_requests',32,'maximum_source_bytes',16777216,'request_admission_required',true,'superseded_assignment_event_id',q.assignment_event_id,'execution_recipe','Discover exact retained authoritative settlement bodies; acquire only under separately valid finite source admission and licensing. Preserve original values and unresolved evidence. Produce independently reviewed settlement source semantics and verification successor; no family acceptance.')) RETURNING event_id INTO ev;
 UPDATE population_top3000_202608_202609_v1.continuation_clear_queue_v6 SET assignment_event_id=ev WHERE clearing_id=new_id;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CONTINUATION_CLASSIFICATION_REPAIRED_V7',ctl||jsonb_build_object('old_clearing_id',q.clearing_id,'new_clearing_id',new_id,'assignment_event_id',ev,'original_task_denominator',8,'original_tasks_unchanged',true,'data_acceptance',false));
END;$repair$;
